import React from "react";
import {Tree} from "react-tree-graph";
import "react-tree-graph/dist/style.css";
import "./categoriesGraphTree.css";
import styledCom from "styled-components";
import Loader from "../../../ui/loader/loader";
import {CategoryType} from "../../../models/category";
import {useGetCategoriesQuery} from "../categoriesApi";
import {useTranslation} from "../../../i18n";

const MainDiv = styledCom.div({
    width: "100%",
    margin: "1%",
    textAlign: "center",
    backgroundColor: "white",
    borderRadius: "12px",
    padding: "0.5%",
    maxWidth: "100%",
});

const CategoriesGraphTree = ({categoryType = CategoryType.Product}) => {
    const windowWidth = window.innerWidth;
    const {data: categories = [], isLoading} = useGetCategoriesQuery({type: categoryType});
    const {t} = useTranslation();

    function createObject(categoryList) {
        const rootCategory = {
            name: categoryType === CategoryType.Service ? t("Service categories") : t("Product categories"),
            textProps: {
                x: -25,
                y: 25,
            },
            children: [],
        };

        const categoryMap = {};

        categoryList.forEach((category) => {
            categoryMap[category.id] = {
                id: category.id,
                name: category.name,
                textProps: {
                    x: -25,
                    y: 25,
                },
                children: [],
            };
        });

        categoryList.forEach((category) => {
            const parentId = category.parentCategoryId;

            if (!parentId || !categoryMap[parentId]) {
                rootCategory.children.push(categoryMap[category.id]);
                return;
            }

            categoryMap[parentId].children.push(categoryMap[category.id]);
        });

        return rootCategory;
    }

    const handleClick = (_, key) => {
        alert(key);
    };

    if (isLoading) {
        return <Loader/>;
    }

    return (
        <MainDiv>
            <Tree
                animated={true}
                data={createObject(categories)}
                gProps={{
                    className: "node",
                    onClick: handleClick,
                }}
                height={700}
                width={windowWidth <= 768 ? windowWidth - 1 : 1200}
            />
        </MainDiv>
    );
};

export default CategoriesGraphTree;
